<script setup lang="ts">
import {ref,watch} from 'vue'
import {open,save} from '@tauri-apps/plugin-dialog'
import {convertFileSrc} from '@tauri-apps/api/core'
import {command,message,desktop} from '../api'
interface Attachment{id:number;name:string;mime:string;bytes:number}
const props=defineProps<{studyId:number;editable:boolean}>()
const items=ref<Attachment[]>([]),busy=ref(false),error=ref(''),removing=ref<Attachment>(),include=ref<number[]>([])
async function load(){try{items.value=await command('list_attachments',{studyId:props.studyId})}catch(e){error.value=message(e)}}
watch(()=>props.studyId,load,{immediate:true})
function closeRemoval(value:boolean){if(!value)removing.value=undefined}
const url=(id:number)=>desktop?convertFileSrc(String(id),'uzi-media'):''
async function add(){busy.value=true;error.value='';try{const files=await open({multiple:true,filters:[{name:'Снимки и видео',extensions:['png','jpg','jpeg','webp','mp4','webm','avi']}]});if(files){for(const path of Array.isArray(files)?files:[files])await command('import_attachment',{studyId:props.studyId,path});await load()}}catch(e){error.value=message(e)}finally{busy.value=false}}
async function exportFile(item:Attachment){try{const path=await save({defaultPath:item.name});if(path)await command('export_attachment',{id:item.id,path})}catch(e){error.value=message(e)}}
async function remove(){if(!removing.value)return;busy.value=true;try{await command('remove_attachment',{id:removing.value.id});include.value=include.value.filter(id=>id!==removing.value?.id);removing.value=undefined;await load()}catch(e){error.value=message(e)}finally{busy.value=false}}
function printed(id:number,checked:boolean){include.value=checked?[...include.value,id]:include.value.filter(value=>value!==id)}
</script>
<template><section class="attachment-section no-print"><div class="section-heading"><h2>Снимки и видео <span>{{items.length}}</span></h2><UButton v-if="editable" icon="i-lucide-paperclip" :loading="busy" @click="add">Добавить файлы</UButton></div><p v-if="editable" class="text-slate-600 mb-5">Файлы сохраняются внутри базы. Снимок — до 25 МБ, видео — до 250 МБ. Для воспроизведения нужен кодек, поддерживаемый Windows.</p><UAlert v-if="error" color="error" variant="soft" :description="error" class="mb-5"/><p v-if="!items.length" class="text-slate-600">Вложений нет.</p><div class="attachments-grid"><div v-for="item in items" :key="item.id" class="attachment-card"><img v-if="item.mime.startsWith('image/')" :src="url(item.id)" :alt="item.name" loading="lazy"><video v-else-if="item.mime!=='video/x-msvideo'" :src="url(item.id)" controls preload="metadata"/><div v-else class="attachment-placeholder"><UIcon name="i-lucide-film"/><p>AVI: сохраните файл для открытия во внешнем проигрывателе.</p></div><strong class="break-all">{{item.name}}</strong><p class="text-slate-600">{{(item.bytes/1024/1024).toFixed(2)}} МБ</p><UCheckbox v-if="item.mime.startsWith('image/')" :model-value="include.includes(item.id)" @update:model-value="printed(item.id,Boolean($event))" label="Включить в печать"/><div class="flex justify-between gap-2"><UButton variant="ghost" icon="i-lucide-download" @click="exportFile(item)">Сохранить файл</UButton><UButton v-if="editable" color="error" variant="ghost" icon="i-lucide-trash-2" @click="removing=item" aria-label="Убрать вложение"/></div></div></div><UModal :open="Boolean(removing)" @update:open="closeRemoval" title="Убрать вложение из исследования?" :description="removing?.name"><template #footer><UButton variant="ghost" color="neutral" @click="removing=undefined">Отмена</UButton><UButton color="error" :loading="busy" @click="remove">Убрать вложение</UButton></template></UModal></section><section v-if="include.length" class="print-only attachment-print"><figure v-for="item in items.filter(i=>include.includes(i.id))" :key="item.id"><img :src="url(item.id)" :alt="item.name"><figcaption>Исследование № {{studyId}} · {{item.name}}</figcaption></figure></section></template>
